locals {
  apps = {
    qa = {
      worflows = {
        name           = "worflows"
        machine_type   = "e2-medium"
        zone           = "us-east1-c"
        image          = "rocky-linux-9-optimized-gcp-v20251017"
        boot_disk_type = "pd-balanced"
        boot_disk_size = 50
        host_patterns  = ["workflows-qa.liftit-sandbox.com"]
        type           = "instance_group"
        paths          = ["/"]
        health_check = {
          port         = 80
          request_path = "/healthz"
        }
      }
    }
    prod = {
      worflows = {
        name           = "worflows"
        machine_type   = "e2-medium"
        zone           = "us-east1-c"
        image          = "rocky-linux-9-optimized-gcp-v20251017"
        boot_disk_type = "pd-ssd"
        boot_disk_size = 50
        host_patterns  = ["workflows.liftit.co"]
        type           = "instance_group"
        paths          = ["/"]
        health_check = {
          port         = 80
          request_path = "/healthz"
        }
      }
      inventarios = {
        name           = "inventarios"
        machine_type   = "e2-medium"
        zone           = "us-east1-c"
        image          = "rocky-linux-9-optimized-gcp-v20251017"
        boot_disk_type = "pd-balanced"
        boot_disk_size = 20
        additional_disks = [
          {
            name           = "inventarios-data"
            type           = "pd-balanced"
            size           = 40
            encryption_key = "${[for item in local.kms_key : item if can(regex(".*/compute-engine$", item))][0]}/cryptoKeys/compute-engine"
          }
        ]
        host_patterns = ["inventarios.liftit.co"]
        type          = "instance_group"
        paths         = ["/"]
        health_check = {
          port         = 80
          request_path = "/healthz"
        }
      }
    }
  }
}

module "apps-vm" {
  for_each             = local.apps[terraform.workspace]
  source               = "git::ssh://git@github.com/liftitapp/tf-modules.git//vm"
  name                 = each.value.name
  machine_type         = each.value.machine_type
  zone                 = each.value.zone
  image                = each.value.image
  boot_disk_type       = each.value.boot_disk_type
  boot_disk_size       = each.value.boot_disk_size
  additional_disks     = each.key == "inventarios" ? each.value.additional_disks : []
  encryption_key       = "${[for item in local.kms_key : item if can(regex(".*/compute-engine$", item))][0]}/cryptoKeys/compute-engine"
  enable_ip_forwarding = true
  service_account      = local.sa["compute-engine"]
  network_tags = [
    "http-backend",
    "ssh",
  ]
  labels                     = local.default_labels
  enable_deletion_protection = true
  enable_alerting            = true
  network_interfaces = [
    {
      network    = local.network
      subnetwork = local.subnet_ids["apps-${terraform.workspace}"]
      static_ip  = true
    }
  ]
  backup_policy         = local.backup_name["daily"]
  alert_email           = "dev@liftit.co"
  create_instance_group = true
  app_port              = 80
  static_ip             = false
}

