file.content:
variable "name" {
  description = "Nombre de la instancia"
  type        = string
}

variable "machine_type" {
  description = "Tipo de máquina (ej. e2-standard-4)"
  type        = string
}

variable "zone" {
  description = "Zona de GCP donde se desplegará la VM"
  type        = string
}

variable "image" {
  description = "Imagen del sistema operativo"
  type        = string
  default     = ""
}

variable "snapshot" {
  description = "Snapshot para crear el disco de arranque"
  type        = string
  default     = ""
}

variable "boot_disk_type" {
  description = "Tipo de disco de arranque (ej. pd-standard, pd-ssd, pd-balanced)"
  type        = string
  default     = "pd-standard"
}

variable "boot_disk_size" {
  description = "Tamaño del disco de arranque en GB"
  type        = number
}

variable "existing_boot_disk" {
  description = "Nombre del disco existente a usar como boot disk (si aplica)"
  type        = string
  default     = ""
}

variable "encryption_key" {
  description = "Clave de cifrado para el disco de arranque"
  type        = string
  default     = ""
}

variable "network_interfaces" {
  description = "Lista de interfaces de red"
  type = list(object({
    network    = string
    subnetwork = string
    nat_ip     = optional(string)
  }))
  default = []
}

variable "additional_disks" {
  description = "Lista de discos adicionales"
  type = list(object({
    name           = string
    size           = number
    type           = string
    snapshot       = optional(string)
    encryption_key = optional(string)
  }))
  default = []
}

variable "enable_ip_forwarding" {
  description = "Habilitar reenvío de IP"
  type        = bool
  default     = false
}

variable "service_account" {
  description = "Cuenta de servicio asociada a la VM"
  type        = string
  default     = ""
}

variable "service_account_scopes" {
  description = "Lista de permisos individuales para la cuenta de servicio"
  type        = list(string)
  default     = ["cloud-platform"]
}

variable "network_tags" {
  description = "Lista de etiquetas de red"
  type        = list(string)
  default     = []
}

variable "labels" {
  description = "Etiquetas de la instancia"
  type        = map(string)
  default     = {}
}

variable "static_ip" {
  description = "Si se debe crear una IP pública estática"
  type        = bool
  default     = false
}

variable "enable_deletion_protection" {
  description = "Protección contra eliminación"
  type        = bool
  default     = false
}

variable "enable_backup" {
  description = "Habilitar estrategia de backup diario para el disco"
  type        = bool
  default     = false
}
variable "backup_policy" {
  description = "Política de backup existente opcional"
  type        = string
  default     = ""
}

variable "backup_days_in_cycle" {
  description = "Número de días entre backups (1 = diario, 7 = semanal)"
  type        = number
  default     = 1
}

variable "backup_start_time" {
  description = "Hora del día para el backup (formato HH:MM)"
  type        = string
  default     = "23:59"
}

variable "backup_retention_days" {
  description = "Cantidad de días que se retienen los snapshots"
  type        = number
  default     = 7
}

variable "alert_email" {
  description = "Correo para recibir alertas"
  type        = string
  default     = ""
}
variable "enable_alerting" {
  description = "Habilitar alerta si la máquina falla"
  type        = bool
  default     = false
}

variable "app_port" {
  description = "Puerto de la aplicación"
  type        = number
}

variable "create_instance_group" {
  description = "Crear un grupo de instancias"
  type        = bool
  default     = false
}

variable "assign_public_ip" {
  description = "Asigna IP pública dinámica si no hay IP estática"
  type        = bool
  default     = false
}

# Dirección IP Global o Regional
resource "google_compute_address" "regional_ip" {
  count  = var.scope == "regional" ? 1 : 0
  name   = "${var.frontend_config.name}-ip"
  region = var.frontend_config.region
  labels = var.labels
}

resource "google_compute_global_address" "global_ip" {
  count  = var.scope == "global" ? 1 : 0
  name   = "${var.frontend_config.name}-global-ip"
  labels = var.labels
}

# Locals auxiliares
locals {
  non_bucket_backends   = [for b in var.backends : b if b.type != "backend_bucket"]
  requires_health_check = length(local.non_bucket_backends) > 0
  default_backend       = var.use_redirect ? null : (length(var.backends) > 0 ? var.backends[0] : null)
}

# Instance Group (si se usa como backend)
resource "google_compute_instance_group" "instance_group" {
  for_each = {
    for b in var.backends : b.name => b
    if b.type == "instance_group"
  }

  name      = "${each.value.name}-instance-group"
  zone      = each.value.zone
  instances = each.value.instances_id
}

resource "google_compute_network_endpoint_group" "zonal_neg" {
  for_each = {
    for b in var.backends : b.name => b
    if b.type == "zonal_neg" && b.neg_id == null
  }

  name         = "${each.value.name}-zonal-neg"
  network      = each.value.network
  subnetwork   = each.value.subnetwork
  zone         = each.value.zone
  default_port = var.zonal_neg_port
}

resource "google_compute_region_network_endpoint_group" "serverless_neg" {
  for_each = {
    for b in var.backends : b.name => b
    if b.type == "serverless_neg" && b.serverless_neg_id == null
  }

  name                  = "${each.value.name}-sneg"
  region                = each.value.region
  network_endpoint_type = "SERVERLESS"

  cloud_run {
    service = each.value.cloud_run_service
    tag     = each.value.cloud_run_tag
  }
}

resource "google_compute_backend_service" "backend" {
  for_each = {
    for b in var.backends : b.name => b
    if b.type != "backend_bucket"
  }

  name                    = "${each.value.name}-service"
  protocol                = "HTTP"
  load_balancing_scheme   = var.load_balancer_scheme
  timeout_sec             = var.timeout_sec
  session_affinity        = try(each.value.session_affinity, null)
  affinity_cookie_ttl_sec = try(each.value.affinity_cookie_ttl_sec, null)
  health_checks = (
    try(each.value.health_check, null) != null
    ? [google_compute_health_check.per_backend[each.key].self_link] # usa custom si existe
    : (length(var.health_checks) > 0
      ? var.health_checks                                  # usa lista global si existe
      : [google_compute_health_check.default[0].self_link] # fallback al default
    )
  )

  dynamic "backend" {
    for_each = (
      each.value.type == "zonal_neg" && each.value.neg_id != null ?
      (terraform.workspace == "prod" ? each.value.neg_id : [each.value.neg_id[0]])
      : each.value.type == "serverless_neg" && each.value.serverless_neg_id != null ?
      [each.value.serverless_neg_id]
      : each.value.type == "instance_group" && each.value.instance_group_id != null ?
      [each.value.instance_group_id]
      : []
    )

    content {
      group          = backend.value != null ? backend.value : (each.value.type == "zonal_neg" ? google_compute_network_endpoint_group.zonal_neg[each.key].id : each.value.type == "serverless_neg" ? google_compute_region_network_endpoint_group.serverless_neg[each.key].id : each.value.type == "instance_group" ? google_compute_instance_group.instance_group[each.key].id : null)
      balancing_mode = each.value.type == "zonal_neg" || each.value.type == "serverless_neg" ? var.balancing_mode : "UTILIZATION"
      max_rate       = each.value.type == "zonal_neg" || each.value.type == "serverless_neg" ? var.max_rate : null
    }
  }

  security_policy = var.cloud_armor_policy
}

resource "google_compute_backend_bucket" "bucket_backend" {
  for_each = {
    for b in var.backends : b.name => b
    if b.type == "backend_bucket"
  }

  name        = "${each.value.name}-bucket"
  bucket_name = each.value.bucket_name
  enable_cdn  = coalesce(each.value.enable_cdn, false)
}

# URL Map para backends (default_service)
resource "google_compute_url_map" "backend" {
  count = var.use_redirect ? 0 : 1
  name  = "${var.frontend_config.name}-url-map"

  # Default global fallback
  default_service = (
    var.backends[0].type == "backend_bucket"
    ? google_compute_backend_bucket.bucket_backend[var.backends[0].name].self_link
    : google_compute_backend_service.backend[var.backends[0].name].self_link
  )

  # Reglas de host → path matcher
  dynamic "host_rule" {
    for_each = {
      for b in var.backends :
      b.name => b.host_patterns
    }
    content {
      hosts        = host_rule.value
      path_matcher = "${host_rule.key}-matcher"
    }
  }

  # Path matchers dinámicos
  dynamic "path_matcher" {
    for_each = {
      for b in var.backends :
      b.name => b
    }
    content {
      name = "${path_matcher.key}-matcher"

      default_service = (
        path_matcher.value.type == "backend_bucket"
        ? google_compute_backend_bucket.bucket_backend[path_matcher.key].self_link
        : google_compute_backend_service.backend[path_matcher.key].self_link
      )

      path_rule {
        paths = path_matcher.value.paths
        service = (
          path_matcher.value.type == "backend_bucket"
          ? google_compute_backend_bucket.bucket_backend[path_matcher.key].self_link
          : google_compute_backend_service.backend[path_matcher.key].self_link
        )
      }
    }
  }
}

# URL Map para redirección por defecto
resource "google_compute_url_map" "redirect" {
  count = var.use_redirect ? 1 : 0

  name = "${var.frontend_config.name}-url-map"

  default_url_redirect {
    https_redirect         = true
    strip_query            = false
    redirect_response_code = "MOVED_PERMANENTLY_DEFAULT"
  }
}

resource "google_compute_target_http_proxy" "http" {
  name    = "${var.frontend_config.name}-http-proxy"
  url_map = var.use_redirect ? google_compute_url_map.redirect[0].self_link : google_compute_url_map.backend[0].self_link
}

resource "google_compute_target_https_proxy" "https" {
  name            = "${var.frontend_config.name}-https-proxy"
  url_map         = var.use_redirect ? google_compute_url_map.redirect[0].self_link : google_compute_url_map.backend[0].self_link
  certificate_map = var.certificate_manager_certificates
}

resource "google_compute_forwarding_rule" "regional" {
  count                 = var.scope == "regional" ? 1 : 0
  name                  = "${var.frontend_config.name}-fw"
  port_range            = var.frontend_config.port
  ip_address            = var.frontend_config.ip_address != null ? var.frontend_config.ip_address : google_compute_address.regional_ip[0].address
  ip_protocol           = var.frontend_config.protocol
  load_balancing_scheme = var.load_balancer_scheme
  target                = google_compute_target_https_proxy.https.self_link
  region                = var.frontend_config.region
  labels                = var.labels
  depends_on            = [google_compute_target_http_proxy.http, google_compute_target_https_proxy.https]
}

resource "google_compute_global_forwarding_rule" "global" {
  count                 = var.scope == "global" ? 1 : 0
  name                  = "${var.frontend_config.name}-fw"
  port_range            = var.frontend_config.port
  ip_address            = var.frontend_config.ip_address != null ? var.frontend_config.ip_address : google_compute_global_address.global_ip[0].address
  ip_protocol           = var.frontend_config.protocol
  load_balancing_scheme = var.load_balancer_scheme
  target                = google_compute_target_https_proxy.https.self_link
  labels                = var.labels
  depends_on            = [google_compute_target_http_proxy.http, google_compute_target_https_proxy.https]
}

resource "google_compute_health_check" "default" {
  count               = (length(var.health_checks) == 0 && local.requires_health_check) ? 1 : 0
  name                = "${var.frontend_config.name}-hc"
  check_interval_sec  = var.health_check_interval_sec
  timeout_sec         = var.health_check_timeout_sec
  healthy_threshold   = var.health_check_healthy_threshold
  unhealthy_threshold = var.health_check_unhealthy_threshold

  http_health_check {
    request_path = var.health_check_request_path
    port         = var.health_check_port
  }
}

resource "google_compute_health_check" "per_backend" {
  for_each = {
    for b in var.backends : b.name => b
    if try(b.health_check, null) != null
  }

  name                = "${each.value.name}-hc"
  check_interval_sec  = var.health_check_interval_sec
  timeout_sec         = var.health_check_timeout_sec
  healthy_threshold   = var.health_check_healthy_threshold
  unhealthy_threshold = var.health_check_unhealthy_threshold

  http_health_check {
    request_path = each.value.health_check.request_path
    port         = each.value.health_check.port
  }
}

