resource "google_compute_address" "static_ip" {
  count  = var.static_ip ? 1 : 0
  name   = "${var.name}-static-ip"
  region = join("-", slice(split("-", var.zone), 0, 2))
}

resource "google_compute_disk" "boot_disk" {
  count = var.existing_boot_disk == "" && (var.image == null || var.image == "") ? 1 : 0
  name  = "${var.name}-boot-disk"
  type  = var.boot_disk_type
  size  = var.boot_disk_size
  zone  = var.zone

  # Si usa snapshot
  snapshot = var.snapshot != "" ? var.snapshot : null

  dynamic "disk_encryption_key" {
    for_each = var.encryption_key != "" ? [1] : []
    content {
      kms_key_self_link = var.encryption_key
    }
  }

  lifecycle {
    ignore_changes = [disk_encryption_key]
  }
}

moved {
  from = google_compute_disk_resource_policy_attachment.attach_backup_boot
  to   = google_compute_disk_resource_policy_attachment.boot_attach_backup
}

resource "google_compute_instance" "vm" {
  name                = var.name
  machine_type        = var.machine_type
  zone                = var.zone
  tags                = var.network_tags
  labels              = var.labels
  enable_display      = false
  deletion_protection = var.enable_deletion_protection
  can_ip_forward      = var.enable_ip_forwarding

  boot_disk {
    dynamic "initialize_params" {
      for_each = var.existing_boot_disk == "" && var.snapshot == "" ? [1] : []
      content {
        image = var.image != "" ? var.image : null
        type  = var.boot_disk_type
        size  = var.boot_disk_size
      }
    }
    source            = var.existing_boot_disk != "" ? var.existing_boot_disk : (var.image == null || var.image == "" ? google_compute_disk.boot_disk[0].self_link : null)
    kms_key_self_link = var.encryption_key
  }

  dynamic "network_interface" {
    for_each = var.network_interfaces
    content {
      network    = network_interface.value.network
      subnetwork = network_interface.value.subnetwork
      dynamic "access_config" {
        for_each = var.static_ip || var.assign_public_ip || lookup(network_interface.value, "nat_ip", null) != null ? [1] : []
        content {
          nat_ip = var.static_ip ? google_compute_address.static_ip[0].address : lookup(network_interface.value, "nat_ip", null)
        }
      }
    }
  }

  service_account {
    email  = var.service_account
    scopes = var.service_account_scopes
  }

  dynamic "attached_disk" {
    for_each = google_compute_disk.additional
    content {
      source = attached_disk.value.self_link
    }
  }
  lifecycle {
    ignore_changes = [
      boot_disk[0].kms_key_self_link,
      metadata,
    ]
  }
}

resource "google_compute_disk" "additional" {
  for_each = { for idx, disk in var.additional_disks : idx => disk }

  name     = each.value.name
  size     = each.value.size
  type     = each.value.type
  zone     = var.zone
  snapshot = lookup(each.value, "snapshot", null)
  dynamic "disk_encryption_key" {
    for_each = lookup(each.value, "encryption_key", null) != null ? [1] : []
    content {
      kms_key_self_link = each.value.encryption_key
    }
  }

  lifecycle {
    ignore_changes = [disk_encryption_key]
  }
}

resource "google_compute_resource_policy" "backup_policy" {
  count  = var.backup_policy == "" ? 1 : 0
  name   = "${var.name}-backup-policy"
  region = join("-", slice(split("-", var.zone), 0, 2))

  snapshot_schedule_policy {
    schedule {
      daily_schedule {
        days_in_cycle = var.backup_days_in_cycle
        start_time    = var.backup_start_time
      }
    }

    retention_policy {
      max_retention_days    = var.backup_retention_days
      on_source_disk_delete = "KEEP_AUTO_SNAPSHOTS" # Opcional: Puedes cambiarlo a "APPLY_RETENTION_POLICY"
    }
  }
}

resource "google_compute_disk_resource_policy_attachment" "boot_attach_backup" {
  count = var.existing_boot_disk == "" && (var.image == null || var.image == "") ? 1 : 0

  name = var.backup_policy != "" ? var.backup_policy : google_compute_resource_policy.backup_policy[0].id
  disk = google_compute_disk.boot_disk[count.index].name
  zone = var.zone
}
resource "google_compute_disk_resource_policy_attachment" "attach_backup" {
  for_each = { for idx, disk in var.additional_disks : idx => disk }
  name     = var.backup_policy != "" ? var.backup_policy : google_compute_resource_policy.backup_policy[0].id
  disk     = google_compute_disk.additional[each.key].name
  zone     = var.zone
}

resource "google_monitoring_notification_channel" "email_channel" {
  count        = var.enable_alerting ? 1 : 0
  display_name = "Email Alert"
  type         = "email"

  labels = {
    email_address = var.alert_email
  }
}
resource "google_monitoring_alert_policy" "vm_down_alert" {
  count        = var.enable_alerting ? 1 : 0
  display_name = "VM Failure Alert"
  combiner     = "OR"

  conditions {
    display_name = "VM Uptime Check"
    condition_threshold {
      filter          = "metric.type=\"compute.googleapis.com/instance/uptime\" AND resource.type=\"gce_instance\""
      comparison      = "COMPARISON_LT"
      threshold_value = 60     # Si la VM tiene menos de 60 segundos de uptime
      duration        = "300s" # Espera 5 minutos antes de activar la alerta

      aggregations {
        alignment_period   = "60s"
        per_series_aligner = "ALIGN_MEAN"
      }
    }
  }

  notification_channels = [google_monitoring_notification_channel.email_channel[0].id]
}

resource "google_compute_instance_group" "fw_instance_group" {
  count     = var.create_instance_group ? 1 : 0
  name      = "${var.name}-ig"
  zone      = var.zone
  instances = [google_compute_instance.vm.id]

  named_port {
    name = "http"
    port = var.app_port
  }

  depends_on = [google_compute_instance.vm]
}

